functions.compute_indexes:
static void compute_indexes(const uint16_t startbit, const uint8_t len, uint8_t endianness, uint16_t *offset_lsb,
                            uint16_t *byte_idx_lsb, uint16_t *byte_idx_msb)
{
    int i = 0;
    uint16_t msb = 0;
    uint16_t lsb = 0;
    uint16_t current_bit_nr = 0;
    if (endianness == 5)
    {
        msb = startbit;
        current_bit_nr = startbit;
        for (i = 0; i < len - 1; i++)
        {
            if (current_bit_nr % 8 == 0)
            {
                current_bit_nr = current_bit_nr + 15;
            }
            else
            {
                current_bit_nr--;
            }
        }
        lsb = current_bit_nr;
        *byte_idx_lsb = lsb / 8;
        *byte_idx_msb = msb / 8;
        *offset_lsb = lsb % 8;
    }
    else
    {
        lsb = startbit;
        msb = lsb + len - 1;
        *byte_idx_msb = msb / 8;
        *byte_idx_lsb = lsb / 8;
        *offset_lsb = lsb % 8;
    }
}

functions.frame_to_local:
static uint64_t frame_to_local(const uint8_t *frame, uint16_t byte_idx_lsb, uint16_t byte_idx_msb, uint8_t endianness)
{
    int i = 0;
    uint64_t target = 0;
    uint8_t *dest = ((void *)0);
    target = frame[byte_idx_lsb];
    dest = (uint8_t *)&target;
    if (endianness == 5)
    {
        for (i = byte_idx_lsb - 1; i >= byte_idx_msb; i--)
        {
            dest++;
            *dest = frame[i];
        }
    }
    else
    {
        for (i = byte_idx_lsb + 1; i <= byte_idx_msb; i++)
        {
            dest++;
            *dest = frame[i];
        }
    }
    return target;
}

functions.extract:
uint64_t extract(const uint8_t *frame, const uint16_t startbit, const uint8_t len, uint8_t signedness,
                 uint8_t endianness)
{
    uint16_t byte_idx_msb = 0;
    uint16_t byte_idx_lsb = 0;
    uint16_t offset_lsb = 0;
    uint64_t target = 0;
    uint64_t mask = 0;
    uint64_t sign_ext_mask = 0;
    compute_indexes(startbit, len, endianness, &offset_lsb, &byte_idx_lsb, &byte_idx_msb);
    target = frame_to_local(frame, byte_idx_lsb, byte_idx_msb, endianness);
    target = target >> offset_lsb;
    mask = ((uint64_t)1 << len) - 1;
    target = target & mask;
    if (signedness == 3)
    {
        if (((uint64_t)1 << (len - 1)) & target)
        {
            sign_ext_mask = ~mask;
            target = target | sign_ext_mask;
        }
    }
    return target;
}

functions.insert:
void insert(uint8_t *frame, uint16_t startbit, uint8_t len, uint64_t can_value, uint8_t endianness)
{
    int i = 0;
    uint8_t *src = ((void *)0);
    uint16_t byte_idx_msb = 0;
    uint16_t byte_idx_lsb = 0;
    uint16_t offset_lsb = 0;
    uint64_t target = 0;
    uint64_t mask = 0;
    uint64_t erase_mask = 0;
    compute_indexes(startbit, len, endianness, &offset_lsb, &byte_idx_lsb, &byte_idx_msb);
    target = frame_to_local(frame, byte_idx_lsb, byte_idx_msb, endianness);
    mask = ((uint64_t)1 << len) - 1;
    erase_mask = ~(mask << offset_lsb);
    target = (target & erase_mask) | (can_value << offset_lsb);
    src = (uint8_t *)&target;
    if (endianness == 5)
    {
        for (i = byte_idx_lsb; i >= byte_idx_msb; i--)
        {
            frame[i] = *src;
            src++;
        }
    }
    else
    {
        for (i = byte_idx_lsb; i <= byte_idx_msb; i++)
        {
            frame[i] = *src;
            src++;
        }
    }
}

functions.encode_uint64_t:
void encode_uint64_t(uint8_t *frame, uint64_t phy_value, uint16_t startbit, uint8_t len, uint8_t endianness,
                     double factor, double offset)
{
    uint64_t can_value = 0;
    can_value = (uint64_t)((phy_value - offset) / factor);
    insert(frame, startbit, len, can_value, endianness);
}

