uint64_t decode_uint64_t(uint8_t *frame, uint16_t startbit, uint8_t len, uint8_t endianness, double factor,
                         double offset)
{
    uint64_t can_value = 0;
    can_value = extract(frame, startbit, len, 2, endianness);
    return (uint64_t)((can_value * factor) + offset);
}

